function setSync(t){const el=$('#syncPill');if(el)el.textContent=t;}
function save(){state.savedAt=new Date().toISOString();let ok=true;try{localStorage.setItem(cacheKey(),JSON.stringify(state));}catch{storageAvailable=false;ok=false;}
 if(supa&&user){clearTimeout(syncTimer);setSync('Da salvare…');syncTimer=setTimeout(push,700);return true;}
 if(!ok)toast('Il browser non può salvare. Esporta il Quaderno.');return ok;}
async function push(){if(!supa||!user)return;clearTimeout(syncTimer);syncTimer=null;if(syncing){pendingPush=true;return;}syncing=true;setSync('Salvataggio…');
 let error;try{({error}=await supa.from('atlante_state').upsert({user_id:user.id,state,updated_at:new Date().toISOString()}));}catch(e){error=e;}
 syncing=false;if(error){setSync('Non salvato, riprovo…');syncTimer=setTimeout(push,5000);}else setSync('Salvato ✓');
 if(pendingPush){pendingPush=false;push();}}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&syncTimer)push();});
async function enter(u){user=u;recovering=false;authMsg='';const local=readLocal(cacheKey());let remote=null,failed=false;
 try{const {data:row,error}=await supa.from('atlante_state').select('state').eq('user_id',u.id).maybeSingle();if(error)throw error;remote=row&&validState(row.state)?norm(row.state):null;}catch{failed=true;}
 if(failed){state=local||blank();toast('Connessione assente: lavori sulla copia di questo dispositivo.');}
 else if(remote&&local&&(local.savedAt||'')>(remote.savedAt||''))state=local;
 else state=remote||local||blank();
 if(!failed&&state!==remote)save();else{try{localStorage.setItem(cacheKey(),JSON.stringify(state));}catch{}}
 setSync(failed?'Non connessa':'Salvato ✓');await checkAccess();render();}
