const GTHEMES=[['love','Relazioni',['Che cosa posso portare di più sincero in un rapporto importante?','Come posso ascoltare meglio una persona a cui tengo?','Di che cosa ho bisogno per sentirmi a mio agio con gli altri?']],['work','Lavoro e progetti',['Come posso far avanzare un progetto a cui tengo?','Che cosa mi frena nel lavoro in questo periodo?','Quale passo concreto posso fare questa settimana?']],['care','Benessere',['Di che cosa ho bisogno per stare meglio in questi giorni?','Dove sto spendendo più energia del necessario?','Che cosa posso concedermi senza sensi di colpa?']]];
const posName=p=>(GPOS.find(x=>x[0]===p)||[0,{passo:'Passo possibile',ostacolo:'Ostacolo',situazione:'Situazione'}[p]||p])[1];
const GQ=[['vedo','Che cosa vedo','Due o tre dettagli dell’immagine: un gesto, un oggetto, un colore.'],['senso','Che cosa significa qui','Collega quei dettagli alla posizione e alla domanda.'],['farei','Che cosa farei','Un passo piccolo e concreto, o una cosa da osservare.']];
let gymOpen=false,gymPick=false;
const rnd=a=>a[Math.floor(Math.random()*a.length)];
function studied(){const txt=data.lessons.filter(l=>state.lessons.includes(l.id)).map(l=>(l.blocks||[]).join(' ')).join(' ');return data.cards.filter(c=>txt.includes(c.name));}
function newGym(id,opt={}){let c=id?cardById(id):null;
 if(!c){const rip=data.cards.filter(x=>status(x.id)===1),st=studied().filter(x=>status(x.id)<2),fresh=data.cards.filter(x=>status(x.id)===0);
  const pool=rip.length&&(Math.random()<.5||!st.length)?rip:st.length?st:fresh.length?fresh.slice(0,10):data.cards;
  const prev=state.gym?.cur?.cardId;const p2=pool.length>1?pool.filter(x=>x.id!==prev):pool;c=rnd(p2);}
 const th=rnd(GTHEMES);state.gym.cur={cardId:c.id,pos:opt.pos||rnd(GPOS)[0],rev:opt.rev!=null?opt.rev:Math.random()<.25,theme:th[0],q:rnd(th[2])};
 state.gym.draft={};gymOpen=false;save();}
