let deferredPrompt=null;
const standalone=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
const isIOS=()=>/iphone|ipad|ipod/i.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
function installBanner(){if(standalone())return '';return `<div class="panel installbox"><div><span class="eyebrow">L’ATLANTE SUL TUO TELEFONO</span><p class="small" style="margin:8px 0 0">Mettilo nella schermata Home: si apre con un tocco, a schermo intero, come un’app.</p></div><button class="button" data-install>Installa l’app</button></div>`;}
function installUI(){const b=$('#installSide');if(b)b.hidden=standalone();}
addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredPrompt=e;installUI();});
addEventListener('appinstalled',()=>{deferredPrompt=null;toast('App installata. La trovi nella schermata Home.');if(location.hash===''||location.hash==='#home')render();});
async function doInstall(){if(deferredPrompt){deferredPrompt.prompt();try{await deferredPrompt.userChoice;}catch{}deferredPrompt=null;return;}
 const ios=isIOS();$('#dialogBody').innerHTML=`<div style="max-width:440px"><span class="eyebrow">INSTALLA L’APP</span><h2 id="dialogTitle" style="margin-top:10px">${ios?'Su iPhone e iPad':'Aggiungi alla schermata Home'}</h2>${ios?'<ol class="installsteps"><li>Apri questa pagina con <strong>Safari</strong>.</li><li>Tocca il tasto <strong>Condividi</strong>, il quadrato con la freccia verso l’alto.</li><li>Scorri e scegli <strong>Aggiungi alla schermata Home</strong>.</li><li>Tocca <strong>Aggiungi</strong>: l’icona dell’Atlante compare tra le tue app.</li></ol>':'<ol class="installsteps"><li>Apri il menu del browser, i tre puntini in alto.</li><li>Scegli <strong>Installa app</strong> oppure <strong>Aggiungi a schermata Home</strong>.</li><li>Conferma: l’icona dell’Atlante compare tra le tue app.</li></ol>'}<p class="help">Apple non permette ai siti di installarsi da soli: per questo su iPhone servono questi due tocchi.</p></div>`;$('#detail').showModal();}
if('serviceWorker' in navigator)addEventListener('load',()=>navigator.serviceWorker.register('sw.js').catch(()=>{}));

