document.addEventListener('click',e=>{
 const o=e.target.closest('[data-qopt]');if(o&&Q&&Q.picked==null){Q.picked=Number(o.dataset.qopt);if(Q.qs[Q.i].options[Q.picked]===Q.qs[Q.i].answer)Q.score++;renderQ();}
 if(e.target.closest('[data-qnext]')&&Q){Q.i++;Q.picked=null;renderQ();$('#qbox')?.scrollIntoView({block:'start',behavior:'smooth'});}
 if(e.target.closest('[data-qretry]')&&Q){$('#main').innerHTML=quizSet(Q.id);renderQ();}
 if(e.target.closest('[data-install]'))doInstall();
 if(e.target.closest('[data-recheck]')){(async()=>{unlockMsg='Controllo…';render();await checkAccess();unlockMsg=full?'':'Non trovo ancora un acquisto con questa email. Se hai appena pagato aspetta un minuto e riprova; se hai usato un’altra email, entra con quella.';if(full)toast('Corso completo sbloccato. Buono studio!');render();})();}
 if(e.target.closest('[data-unlock]')){(async()=>{const c=($('#unlockCode')?.value||'').trim();if(!c){unlockMsg='Scrivi il codice che hai ricevuto.';render();return;}let ok=false;try{const {data:r,error}=await supa.rpc('redeem_code',{c});ok=!error&&r===true;}catch{}if(ok)ok=await loadPaid();if(ok){full=true;unlockMsg='';toast('Corso completo sbloccato. Buono studio!');}else unlockMsg='Codice non valido o già usato, oppure la connessione è caduta. Controlla di averlo copiato bene e riprova.';render();})();}
 if(e.target.closest('[data-ddraw]')){const L=LAYOUTS[D.layout];D.cards=shuffle(data.cards).slice(0,L.pos.length).map(c=>c.id);D.rev=D.cards.map(()=>false);renderDiaryForm();}
 if(e.target.closest('[data-dsave]')){const n=LAYOUTS[D.layout].pos.length;if(D.cards.filter(Boolean).length<n){toast('Scegli una carta per ogni posizione.');return;}const s={id:globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random(),date:new Date().toISOString(),layout:D.layout,question:D.question.trim(),cards:D.cards.map((id,i)=>({id,rev:!!D.rev[i]})),text:D.text.trim(),outcome:''};state.spreads.push(s);D={layout:D.layout,cards:[],rev:[],question:'',text:''};save();render();toast('Stesa salvata nel diario.');}
 const del=e.target.closest('[data-ddel]');if(del&&confirm('Eliminare questa stesa dal diario?')){state.spreads=state.spreads.filter(s=>s.id!==del.dataset.ddel);save();render();}
});
document.addEventListener('change',e=>{
 if(e.target.id==='dLayout'){D.layout=e.target.value;renderDiaryForm();}
 if(e.target.matches('[data-dcard]')){D.cards[Number(e.target.dataset.dcard)]=e.target.value;renderDiaryForm();}
 if(e.target.matches('[data-drev]')){D.rev[Number(e.target.dataset.drev)]=e.target.checked;renderDiaryForm();}
});
document.addEventListener('input',e=>{
 if(e.target.id==='dQuestion')D.question=e.target.value;
 if(e.target.id==='dText')D.text=e.target.value;
 if(e.target.matches('[data-exchk]')){const k=e.target.dataset.exchk,j=Number(e.target.dataset.j),x=state.exercises[k]||{text:'',date:new Date().toISOString()};x.checks=Array.from({length:3},(_,i)=>!!x.checks?.[i]);x.checks[j]=e.target.checked;state.exercises[k]=x;save();}
  if(e.target.matches('[data-ex]')){const k=e.target.dataset.ex,v=e.target.value;if(v.trim()||state.exercises[k]?.checks?.some(Boolean))state.exercises[k]={...(state.exercises[k]||{}),text:v,date:new Date().toISOString()};else delete state.exercises[k];save();const n=document.querySelector(`[data-exnote="${k}"]`);if(n)n.textContent=v.trim()?'Salvato nel Quaderno ✓':'Si salva mentre scrivi.';}
 if(e.target.matches('[data-doutcome]')){const s=state.spreads.find(x=>x.id===e.target.dataset.doutcome);if(s){s.outcome=e.target.value;save();}}
});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0});$('#main').focus({preventScroll:true});});
fetch('course-data.json').then(r=>{if(!r.ok)throw Error('Corso non disponibile');return r.json();}).then(async d=>{data=d;state=norm(state);if(supa){let u=null;try{const {data:s}=await supa.auth.getSession();u=s?.session?.user||null;}catch{}if(u&&!recovering)return enter(u);}render();}).catch(()=>{$('#main').innerHTML='<div class="empty"><h2>Il corso non si è caricato.</h2><p>Ricarica la pagina quando la connessione è disponibile. Intanto puoi studiare con i PDF del corso.</p></div>';});
